// Generated Zip Puzzle Catalog with 100 Verified Levels and Walls
import '../models/grid_point.dart';
import '../models/level_definition.dart';
import '../models/wall.dart';

class ZipCatalog {
  static const int totalLevels = 100;

  static final List<LevelDefinition> _levels =
      _interleaveLevels(_generateRawCatalog());

  static List<LevelDefinition> get allLevels => _levels;

  static LevelDefinition getLevel(int levelNumber) {
    if (levelNumber < 1 || levelNumber > totalLevels) {
      throw RangeError('Level must be between 1 and $totalLevels');
    }
    return _levels[levelNumber - 1];
  }

  static List<LevelDefinition> _interleaveLevels(List<LevelDefinition> raw) {
    final easyList =
        raw.where((l) => l.difficulty == ZipDifficulty.easy).toList();
    final mediumList =
        raw.where((l) => l.difficulty == ZipDifficulty.medium).toList();
    final hardList =
        raw.where((l) => l.difficulty == ZipDifficulty.hard).toList();
    final expertList =
        raw.where((l) => l.difficulty == ZipDifficulty.expert).toList();

    // Interleaved sequence matching: "1 easy, 2 hard, therd meddem like"
    // Repeating 10-step template: 2 Easy, 3 Hard, 3 Medium, 2 Expert = 10
    final template = [
      ZipDifficulty.easy,
      ZipDifficulty.hard,
      ZipDifficulty.medium,
      ZipDifficulty.expert,
      ZipDifficulty.easy,
      ZipDifficulty.hard,
      ZipDifficulty.medium,
      ZipDifficulty.hard,
      ZipDifficulty.medium,
      ZipDifficulty.expert,
    ];

    int eIdx = 0;
    int mIdx = 0;
    int hIdx = 0;
    int exIdx = 0;

    final List<LevelDefinition> result = [];
    for (int i = 0; i < 100; i++) {
      final diff = template[i % template.length];
      LevelDefinition base;
      switch (diff) {
        case ZipDifficulty.easy:
          base = easyList[eIdx++];
          break;
        case ZipDifficulty.medium:
          base = mediumList[mIdx++];
          break;
        case ZipDifficulty.hard:
          base = hardList[hIdx++];
          break;
        case ZipDifficulty.expert:
          base = expertList[exIdx++];
          break;
      }
      result.add(base.copyWith(levelNumber: i + 1));
    }

    return result;
  }

